/* DAYA STUDIO — Local-first operational prototype. Demo auth is NOT production authentication. */
'use strict';
const DB_NAME='daya-clothing-studio'; const DB_VERSION=1;
const STORES=['products','customers','orders','users','tasks','checklist','outbox','events','settings','meta'];
const DEFAULT_EMAIL='dayaclothing.mx@gmail.com';
const IMG=['blusa-lino','cardigan-arena','vestido-terracota','jeans-azul','bolso-borgona','sandalias-nude','aretes-dorados','blusa-rosa','bolso-trenzado'].map(x=>'assets/'+x+'.webp');
const CATEGORIES=['Blusas','Tejidos','Vestidos','Denim','Bolsos','Calzado','Accesorios'];
const ORDER_STATUSES=['Nuevo','Preparando','Enviado','Entregado','Cancelado'];
const PRODUCT_STATUSES=['Activo','Borrador','Archivado'];
const navs=[['dashboard','Resumen','layout-dashboard'],['products','Productos','package'],['orders','Pedidos','shopping-bag'],['requests','Solicitudes web','mail'],['customers','Clientes','users'],['users','Equipo','user-cog'],['tasks','Seguimiento','clipboard-list'],['launch','Publicación','check-check'],['settings','Configuración','settings']];
const ICON_NAMES=new Set(["layout-dashboard", "package", "shopping-bag", "users", "user-cog", "clipboard-list", "check-check", "settings", "plus", "search", "sun", "moon", "log-out", "arrow-up-right", "alert-triangle", "check", "clock", "x", "trash", "edit", "download", "mail", "grid", "list", "sparkles", "chevron-right", "upload", "info"]);
const I=n=>`<span class="app-icon" aria-hidden="true" style="--icon:url('assets/icons/${ICON_NAMES.has(n)?n:'info'}.svg')"></span>`;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(Number(n||0));
const date=s=>new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(s||Date.now()));
const todayOffset=n=>new Date(Date.now()+n*86400000).toISOString();
const uid=(type='DC')=>type+'-'+Math.random().toString(36).slice(2,9).toUpperCase();
const storage={db:null,async init(){return new Promise((res,rej)=>{const q=indexedDB.open(DB_NAME,DB_VERSION);q.onupgradeneeded=()=>{for(const s of STORES)if(!q.result.objectStoreNames.contains(s))q.result.createObjectStore(s,{keyPath:'id'});};q.onsuccess=()=>{this.db=q.result;res()};q.onerror=()=>rej(q.error)});},async all(s){return new Promise((res,rej)=>{const tx=this.db.transaction(s,'readonly');const q=tx.objectStore(s).getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})},async get(s,id){return new Promise((res,rej)=>{const q=this.db.transaction(s,'readonly').objectStore(s).get(id);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})},async put(s,obj){return new Promise((res,rej)=>{const q=this.db.transaction(s,'readwrite').objectStore(s).put(obj);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})},async del(s,id){return new Promise((res,rej)=>{const q=this.db.transaction(s,'readwrite').objectStore(s).delete(id);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})},async clear(s){return new Promise((res,rej)=>{const q=this.db.transaction(s,'readwrite').objectStore(s).clear();q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})},async batch(ops){const names=[...new Set(ops.map(x=>x.s))];return new Promise((res,rej)=>{const tx=this.db.transaction(names,'readwrite');tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error);for(const op of ops){const store=tx.objectStore(op.s);if(op.delete)store.delete(op.id);else store.put(op.data)}})}};
let state={user:null,section:'dashboard',query:'',filter:'Todos',gallery:false,theme:localStorage.getItem('daya-theme')||'light',data:{}};
document.documentElement.dataset.theme=state.theme;
const hashPass=async p=>{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('DAYA_LOCAL_DEMO_2026::'+p));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')};
async function seed(force=false){const m=await storage.get('meta','seeded');if(m&&!force)return;for(const s of STORES)await storage.clear(s);
const products=[
['Blusa de lino Alma','BL-001','Blusas',799,16,IMG[0],'Activo','XS,S,M,L','Marfil,Blanco',520],
['Cárdigan tejido Siena','TJ-004','Tejidos',1090,9,IMG[1],'Activo','S,M,L','Arena,Café',670],
['Vestido midi Terra','VE-017','Vestidos',1490,4,IMG[2],'Activo','S,M,L','Terracota,Negro',910],
['Jeans rectos Nora','DN-010','Denim',1190,23,IMG[3],'Activo','24,26,28,30','Azul índigo',720],
['Bolso estructurado Roma','BO-006','Bolsos',1390,7,IMG[4],'Activo','Única','Borgoña,Negro',820],
['Sandalias Alina','CA-014','Calzado',990,12,IMG[5],'Activo','23,24,25,26','Nude,Camel',590],
['Arracadas Aura doradas','AC-009','Accesorios',390,27,IMG[6],'Activo','Única','Dorado',150],
['Blusa Clara rosa','BL-019','Blusas',690,0,IMG[7],'Borrador','S,M,L','Rosa palo',410],
['Bolso tejido Elisa','BO-013','Bolsos',1250,5,IMG[8],'Activo','Única','Café,Coñac',730]
].map((x,i)=>({id:`PR-${1001+i}`,name:x[0],sku:x[1],category:x[2],price:x[3],stock:x[4],image:x[5],status:x[6],sizes:x[7],colors:x[8],cost:x[9],minStock:6,created:todayOffset(-30+i)}));
const customers=[['Sofía Ramírez','sofia.ramirez@example.com','6565550101','Nuevo Casas Grandes'],['Mariana González','mariana.gonzalez@example.com','6565550102','Casas Grandes'],['Valeria Torres','valeria.torres@example.com','6565550103','Nuevo Casas Grandes'],['Camila Ortega','camila.ortega@example.com','6565550104','Ciudad Juárez'],['Ana Lucía Díaz','ana.diaz@example.com','6565550105','Nuevo Casas Grandes'],['Regina Flores','regina.flores@example.com','6565550106','Chihuahua']].map((x,i)=>({id:`CL-${2001+i}`,name:x[0],email:x[1],phone:x[2],city:x[3],created:todayOffset(-30+i*4),note:''}));
const orderdata=[[0,0,1,'Entregado',-6,'Instagram'],[1,2,1,'Entregado',-5,'WhatsApp'],[2,3,2,'Preparando',-3,'Web'],[3,4,1,'Enviado',-2,'Instagram'],[4,1,1,'Nuevo',-1,'WhatsApp'],[5,6,2,'Entregado',-1,'Web'],[0,5,1,'Nuevo',0,'Instagram'],[2,8,1,'Preparando',0,'WhatsApp']];
const orders=orderdata.map((x,i)=>({id:'DY-'+String(2401+i),customerId:customers[x[0]].id,items:[{productId:products[x[1]].id,qty:x[2],price:products[x[1]].price}],total:x[2]*products[x[1]].price,status:x[3],date:todayOffset(x[4]),channel:x[5],note:''}));
const users=[{id:'US-01',name:'Administración Daya',email:'admin@daya.local',role:'Administrador',status:'Activo',passwordHash:await hashPass('DayaDemo2026!')},{id:'US-02',name:'Operación Daya',email:'operador@daya.local',role:'Operador',status:'Activo',passwordHash:await hashPass('DayaStaff2026!')},{id:'US-03',name:'Vista catálogo',email:'consulta@daya.local',role:'Consulta',status:'Activo',passwordHash:await hashPass('DayaView2026!')}];
const tasks=[['Decisión','Canales de venta prioritarios','Confirmar si comenzaremos por Instagram, WhatsApp o tienda web.','Pendiente'],['Pendiente','Fotografía definitiva del catálogo','Sustituir las imágenes editoriales por fotografías reales.','En curso'],['Riesgo','Acceso compartido entre dispositivos','La base de datos local no sincroniza iPad y escritorio; activar Supabase antes de operar.','Abierto'],['Próximo paso','Validar flujo de pedidos','Revisar altas, reservas de inventario y cancelaciones con la dueña.','Pendiente'],['Riesgo','Envío real de correos','La bandeja de pruebas solo simula envíos hasta configurar proveedor transaccional.','Abierto']].map((x,i)=>({id:`TS-${i+1}`,type:x[0],title:x[1],detail:x[2],status:x[3],date:todayOffset(-i)}));
const checklist=[['Autenticación y control de permisos',false],['RLS y políticas en Supabase',false],['Persistencia y sincronización entre equipos',false],['Imágenes definitivas y licencia de uso',false],['Correo transaccional verificado',false],['Diseño responsive iPad vertical / horizontal',false],['Pruebas de pedidos y stock',false],['Dominio, SSL y DNS verificados',false],['Copias de seguridad y recuperación',false],['Publicación en entorno de producción',false]].map((x,i)=>({id:`CK-${i+1}`,title:x[0],done:x[1]}));
const settings={id:'shop',brand:'Daya Clothing',email:DEFAULT_EMAIL,testEmail:DEFAULT_EMAIL,domain:'',cloudflareProject:'',supabaseUrl:'',siteUrl:'',sender:'Daya Clothing',theme:'light'};
await storage.batch([...products.map(data=>({s:'products',data})),...customers.map(data=>({s:'customers',data})),...orders.map(data=>({s:'orders',data})),...users.map(data=>({s:'users',data})),...tasks.map(data=>({s:'tasks',data})),...checklist.map(data=>({s:'checklist',data})),{s:'settings',data:settings},{s:'meta',data:{id:'seeded',at:new Date().toISOString()}}]);}
async function load(){const entries=await Promise.all(STORES.map(async s=>[s,await storage.all(s)]));state.data=Object.fromEntries(entries);}
function all(s){return state.data[s]||[]}
function me(){return state.user}
function admin(){return me()?.role==='Administrador'}
function canEdit(s){if(admin())return true;if(me()?.role==='Operador')return ['customers','orders','tasks'].includes(s);return false}
function canView(s){if(admin())return true;return me()?.role==='Consulta' ? !['users','settings','customers','orders','requests'].includes(s) : !['users','settings'].includes(s)}
async function log(action){const d={id:uid('EV'),text:action,user:me()?.name||'Sistema',date:new Date().toISOString()};await storage.put('events',d)}
function flash(text,error=false){const el=document.getElementById('toast-layer');el.innerHTML=`<div class="toast ${error?'error':''}">${e(text)}</div>`;clearTimeout(flash.t);flash.t=setTimeout(()=>el.innerHTML='',3500)}
function statusPill(s){let color=['Activo','Entregado','Completado','Listo'].includes(s)?'green':['Preparando','Enviado','En curso','Pendiente','Nuevo'].includes(s)?'orange':['Cancelado','Archivado','Abierto','Inactivo'].includes(s)?'red':'gray';return `<span class="pill ${color}">${e(s)}</span>`}
function rolePill(s){return `<span class="pill ${s==='Administrador'?'green':'neutral'}">${e(s)}</span>`}
async function login(email,password){const u=all('users').find(x=>x.email.toLowerCase()===email.toLowerCase()&&x.status==='Activo');if(!u||u.passwordHash!==(await hashPass(password)))throw Error('Correo o contraseña incorrectos.');state.user={id:u.id,name:u.name,email:u.email,role:u.role};sessionStorage.setItem('daya-session',JSON.stringify({userId:u.id,expiresAt:Date.now()+12*3600_000}));state.section='dashboard';location.hash='dashboard';render();flash('Acceso de demostración iniciado');}
function logout(){sessionStorage.removeItem('daya-session');state.user=null;state.section='dashboard';location.hash='';render()}
function loginUI(){document.getElementById('app').innerHTML=`<main class="login" id="studio-main" tabindex="-1"><section class="login-art"><div class="login-brand"><img src="assets/daya-mark.svg" width="58" height="58" alt=""/><div>DAYA<span>CLOTHING / STUDIO LOCAL</span></div></div><div class="login-hero">La esencia de cada detalle.</div><div class="login-art-footer">OPERACIÓN DE TIENDA <span style="margin:0 12px">·</span> EDICIÓN 01 / 2026</div></section><section class="login-panel"><div class="login-box"><div class="kicker">STUDIO LOCAL</div><h1>Bienvenida a Daya.</h1><p class="subtext">Tu catálogo y operación anterior, guardados en este navegador.</p><a class="admin-shop-link" href="tienda.html">← Volver a la tienda</a><form id="login-form" class="stack"><div class="field"><label for="email">Correo electrónico</label><input id="email" type="email" name="email" autocomplete="username" placeholder="tu@correo.com" required value="admin@daya.local"/></div><div class="field"><label for="password">Contraseña</label><input id="password" type="password" name="password" autocomplete="current-password" placeholder="Tu contraseña" required value="DayaDemo2026!" /></div><button class="btn btn-primary" type="submit">Entrar al panel ${I('arrow-up-right')}</button></form><div class="login-demos"><p><strong>Acceso local de demostración</strong></p><small>Administradora: admin@daya.local / DayaDemo2026!</small><small>Operador: operador@daya.local / DayaStaff2026!</small><small>Consulta: consulta@daya.local / DayaView2026!</small><small style="margin-top:8px">No usar para almacenar clientes reales ni contraseñas personales.</small></div><p class="login-credits">Daya Clothing · Studio local · Sin sincronización remota</p></div></section></main>`}
function sideNav(){return navs.filter(x=>canView(x[0])&&(!['settings','users'].includes(x[0])||admin())).map(([id,label,ic])=>`<button type="button" class="nav-btn ${state.section===id?'active':''}" data-nav="${id}" title="${e(label)}" aria-label="${e(label)}" aria-current="${state.section===id?'page':'false'}">${I(ic)}<span>${label}</span>${id==='orders'?`<small>${all('orders').filter(o=>o.status==='Nuevo').length}</small>`:''}</button>`).join('')}
function shell(body){let u=me();const navScroll=document.querySelector('.sidebar')?.scrollLeft||0;document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-mark" src="assets/daya-mark.svg" width="48" height="48" alt=""/><div class="brand-copy"><div class="brand-symbol">DAYA</div><div class="brand-desc">STUDIO LOCAL</div></div></div><div class="side-label">OPERACIÓN</div><nav aria-label="Secciones del panel">${sideNav()}</nav><a class="storefront-link" href="tienda.html">Ver tienda pública ${I('arrow-up-right')}</a><div class="side-bottom"><div class="side-status"><div class="side-avatar">${e(u.name[0])}</div><div><div class="side-user">${e(u.name)}</div><div class="side-meta">${e(u.role)}</div></div></div><div class="side-actions"><button class="side-action" data-action="theme" title="Cambiar tema" aria-label="Cambiar tema">${I(state.theme==='dark'?'sun':'moon')} <span>Tema</span></button><button class="side-action" data-action="logout" title="Cerrar sesión" aria-label="Cerrar sesión">${I('log-out')} <span>Salir</span></button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs">Studio local <span style="padding:0 10px;color:var(--muted)">/</span> <strong>${e(navs.find(n=>n[0]===state.section)?.[1]||'Resumen')}</strong></div><div class="top-actions"><span class="date-label">${new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span><span class="pill orange" title="Los datos están almacenados en este navegador">Solo este navegador</span><button class="icon-btn" data-action="theme" title="Tema claro u oscuro" aria-label="Cambiar tema">${I(state.theme==='dark'?'sun':'moon')}</button><button class="icon-btn top-logout" data-action="logout" title="Cerrar sesión" aria-label="Cerrar sesión">${I('log-out')}</button></div></header><main class="workspace-main" id="studio-main" tabindex="-1">${body}</main></div></div>`;document.querySelector('.sidebar').scrollLeft=navScroll}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${e(kicker)}</div><h1>${e(title)}</h1><p>${e(desc)}</p></div>${action?`<div class="heading-action">${action}</div>`:''}</div>`}
function addBtn(s,label){return canEdit(s)?`<button class="btn btn-primary" data-add="${s}">${I('plus')}${e(label)}</button>`:''}
function dashboard(){const products=all('products'),orders=all('orders'),customers=all('customers');const sold=orders.filter(o=>o.status!=='Cancelado');const sales=sold.reduce((a,b)=>a+b.total,0);const pending=orders.filter(o=>['Nuevo','Preparando'].includes(o.status)).length;const low=products.filter(p=>p.stock<=p.minStock&&p.status!=='Archivado');const last=orders.slice().sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5);
const chart=Array.from({length:7},(_,i)=>{const d=new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10);return{day:new Intl.DateTimeFormat('es-MX',{weekday:'short'}).format(new Date(d+'T12:00:00')).slice(0,3),v:orders.filter(o=>o.date.slice(0,10)===d&&o.status!=='Cancelado').reduce((sum,o)=>sum+o.total,0)}});const max=Math.max(...chart.map(x=>x.v),100);
return heading('DAYA / TU ESPACIO','Tu tienda, al día.','Una mirada clara a lo que está sucediendo en Daya Clothing.',`<button class="btn btn-primary" data-add="orders">${I('plus')} Nuevo pedido</button>`)+`<div class="overview"><section class="feature-hero"><div><div class="kicker" style="color:#f0bacb">NUEVA TEMPORADA / STUDIO</div><h2>Lo esencial se construye con intención.</h2><button class="hero-link" data-nav="products">Ver catálogo ${I('arrow-up-right')}</button></div></section><section class="next-step"><div class="eyebrow">PRÓXIMO EN LA AGENDA</div><h3>El siguiente capítulo de Daya</h3><p>Antes de publicar, conecta la base de datos compartida y el servicio de correo. El panel ya permite probar todos los flujos principales con datos locales.</p><button class="btn btn-small" data-nav="launch">Revisar publicación ${I('chevron-right')}</button></section></div><div class="metric-grid"><div class="metric"><div class="metric-label">Ventas registradas</div><div class="metric-number">${fmt(sales)}</div><div class="metric-foot">VENTAS DE EJEMPLO / TOTAL</div></div><div class="metric"><div class="metric-label">Pedidos por atender</div><div class="metric-number">${pending.toString().padStart(2,'0')}</div><div class="metric-foot" style="color:var(--orange)">REQUIEREN SEGUIMIENTO</div></div><div class="metric"><div class="metric-label">Clientes registrados</div><div class="metric-number">${customers.length.toString().padStart(2,'0')}</div><div class="metric-foot">BASE LOCAL</div></div><div class="metric"><div class="metric-label">Atención de inventario</div><div class="metric-number">${low.length.toString().padStart(2,'0')}</div><div class="metric-foot" style="color:var(--orange)">STOCK BAJO / CERO</div></div></div><div class="dashboard-cols"><section><div class="section-head"><h2>Pedidos recientes</h2><button class="link-btn" data-nav="orders">Ver todos ${I('arrow-up-right')}</button></div><div class="surface"><div class="table-wrap"><table class="data-table" style="min-width:540px"><thead><tr><th>Pedido</th><th>Cliente</th><th>Importe</th><th>Estado</th></tr></thead><tbody>${last.map(o=>`<tr><td><button class="link-btn mono" data-edit="orders" data-id="${o.id}">${e(o.id)}</button></td><td>${e(customers.find(c=>c.id===o.customerId)?.name||'Cliente eliminado')}</td><td><strong>${fmt(o.total)}</strong></td><td>${statusPill(o.status)}</td></tr>`).join('')}</tbody></table></div></div><div class="section-head" style="margin-top:30px"><h2>Movimiento de ventas</h2><span class="tiny muted">ÚLTIMOS 7 DÍAS</span></div><div class="surface surface-pad"><div class="mini-chart">${chart.map(x=>`<div class="chart-col" title="${e(x.day)}: ${fmt(x.v)}"><div class="chart-bar" style="--barh:${Math.max(5,x.v/max*100)}%"></div><span>${e(x.day)}</span></div>`).join('')}</div></div></section><section><div class="section-head"><h2>Inventario a vigilar</h2><button class="link-btn" data-nav="products">Ver productos ${I('arrow-up-right')}</button></div><div class="surface surface-pad">${low.slice(0,5).map(p=>`<div class="product-mini"><img src="${e(p.image)}" alt="${e(p.name)}" loading="lazy"/><div class="grow"><strong>${e(p.name)}</strong><small>SKU ${e(p.sku)} · ${p.stock===0?'Agotado':p.stock+' disponibles'}</small><div class="stock-meter"><i style="--meter:${Math.min(p.stock/Math.max(p.minStock*2,1)*100,100)}%"></i></div></div>${statusPill(p.stock===0?'Sin stock':'Stock bajo')}</div>`).join('')||'<div class="empty">No hay productos con stock bajo.</div>'}</div><p class="tiny muted" style="margin-top:14px">DATOS DE EJEMPLO · NO REPRESENTAN VENTAS REALES</p></section></div>`}
function queryFilter(collection,fn){const q=state.query.toLocaleLowerCase('es');return collection.filter(x=>fn(x,q)&& (state.filter==='Todos'||(x.status===state.filter||x.category===state.filter||x.role===state.filter)))}
function table(headers,body,empty='No encontramos resultados para esa búsqueda.'){return `<div class="surface"><div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}"><div class="empty"><h3>Sin coincidencias</h3><p>${e(empty)}</p><button class="btn btn-small" data-action="reset-filter">Limpiar filtros</button></div></td></tr>`}</tbody></table></div><div class="table-foot"><span>${body?(body.match(/<tr>/g)||[]).length:0} resultados visibles</span><span>Los cambios se guardan en este dispositivo</span></div></div>`}
function filters(options){return `<div class="filters"><label class="search-box">${I('search')}<input id="page-search" type="search" aria-label="Buscar registros" placeholder="Buscar por nombre, código o correo…" value="${e(state.query)}" /></label><div class="actions-row"><select id="page-filter" class="filter-select" aria-label="Filtrar lista"><option>Todos</option>${options.map(o=>`<option ${o===state.filter?'selected':''}>${e(o)}</option>`).join('')}</select>${state.section==='products'?`<button class="icon-btn" data-action="toggle-gallery" title="Cambiar vista" aria-label="${state.gallery?'Mostrar tabla':'Mostrar galería'}">${I(state.gallery?'list':'grid')}</button>`:''}</div></div>`}
function productsPage(){let filtered=queryFilter(all('products'),(p,q)=>[p.name,p.sku,p.category,p.colors].join(' ').toLocaleLowerCase('es').includes(q));const content=state.gallery?`<div class="gallery">${filtered.map(p=>`<article class="gallery-item"><img src="${e(p.image)}" alt="${e(p.name)}"/><div class="info"><div class="tiny muted">${e(p.category)} · ${e(p.sku)}</div><strong>${e(p.name)}</strong><div class="price">${fmt(p.price)}</div><div class="info-bottom">${statusPill(p.status)}<button class="link-btn" data-edit="products" data-id="${p.id}">Ver ${I('chevron-right')}</button></div></div></article>`).join('')}</div>`:table(['Producto','Categoría','Precio','Inventario','Estado','Acciones'],filtered.map(p=>`<tr><td><div class="product-cell"><img src="${e(p.image)}" alt="" loading="lazy"/><div><strong>${e(p.name)}</strong><small>${e(p.sku)}</small></div></div></td><td>${e(p.category)}</td><td><strong>${fmt(p.price)}</strong></td><td>${p.stock<=p.minStock?`<span style="color:var(--orange)">${p.stock} unid.</span>`:`${p.stock} unid.`}</td><td>${statusPill(p.status)}</td><td><button class="link-btn" data-edit="products" data-id="${p.id}">${canEdit('products')?'Editar':'Ver'} ${I('chevron-right')}</button></td></tr>`).join(''));
return heading('CATÁLOGO / COLECCIÓN','Productos & colección','Gestiona cada pieza, sus variantes y su disponibilidad.',addBtn('products','Nuevo producto'))+filters([...CATEGORIES])+ (filtered.length?content:emptyView('No hay productos','Prueba otro término o registra un nuevo producto.','products'))}
function ordersPage(){const c=all('customers');const filtered=queryFilter(all('orders').slice().sort((a,b)=>new Date(b.date)-new Date(a.date)),(o,q)=>[o.id,o.channel,c.find(x=>x.id===o.customerId)?.name].join(' ').toLocaleLowerCase('es').includes(q));return heading('VENTAS / CONTROL','Pedidos','De la confirmación a la entrega, con cada detalle bajo control.',addBtn('orders','Nuevo pedido'))+filters(ORDER_STATUSES)+table(['Pedido / Fecha','Cliente','Canal','Productos','Total','Estado','Acción'],filtered.map(o=>`<tr><td><strong>${e(o.id)}</strong><div class="mono">${date(o.date)}</div></td><td>${e(c.find(x=>x.id===o.customerId)?.name||'No disponible')}</td><td>${e(o.channel)}</td><td>${o.items.reduce((s,i)=>s+i.qty,0)} artículos</td><td><strong>${fmt(o.total)}</strong></td><td>${statusPill(o.status)}</td><td><button class="link-btn" data-edit="orders" data-id="${o.id}">${canEdit('orders')?'Gestionar':'Ver'} ${I('chevron-right')}</button></td></tr>`).join(''))}
function customersPage(){const orders=all('orders');const filtered=all('customers').filter(c=>[c.name,c.email,c.phone,c.city].join(' ').toLocaleLowerCase('es').includes(state.query.toLocaleLowerCase('es')));return heading('RELACIONES / CLIENTAS','Nuestra comunidad','Conserva los datos de contacto y un historial claro de cada compra.',addBtn('customers','Añadir cliente'))+filters([])+table(['Cliente','Contacto','Ciudad','Pedidos','Desde','Acción'],filtered.map(c=>`<tr><td><div class="customer-cell"><strong>${e(c.name)}</strong><small>${e(c.id)}</small></div></td><td>${e(c.email)}<div class="mono">${e(c.phone)}</div></td><td>${e(c.city)}</td><td>${orders.filter(o=>o.customerId===c.id).length}</td><td>${date(c.created)}</td><td><button class="link-btn" data-edit="customers" data-id="${c.id}">${canEdit('customers')?'Editar':'Ver'} ${I('chevron-right')}</button></td></tr>`).join(''))}
function usersPage(){const filtered=queryFilter(all('users'),(u,q)=>[u.name,u.email,u.role].join(' ').toLowerCase().includes(q));return heading('ACCESOS / EQUIPO','Personas & permisos','Cada integrante accede únicamente a las funciones que necesita.',addBtn('users','Invitar integrante'))+`<div class="notice"><strong>Permisos demostrativos:</strong> la restricción de roles funciona dentro de esta interfaz local. Antes de producción se implementará autorización en el servidor y políticas RLS en Supabase.</div>`+filters(['Administrador','Operador','Consulta'])+table(['Integrante','Correo','Perfil','Estado','Acción'],filtered.map(u=>`<tr><td><strong>${e(u.name)}</strong></td><td>${e(u.email)}</td><td>${rolePill(u.role)}</td><td>${statusPill(u.status)}</td><td><button class="link-btn" data-edit="users" data-id="${u.id}">Editar ${I('chevron-right')}</button></td></tr>`).join(''))}
function tasksPage(){let t=all('tasks');const pending=t.filter(x=>x.status!=='Resuelto');const sections=['Decisión','Pendiente','Riesgo','Próximo paso'];return heading('ORGANIZACIÓN / RUTA','Seguimiento','Decisiones, bloqueos y siguientes acciones en un mismo lugar.',addBtn('tasks','Registrar nota'))+`<div class="metric-grid" style="grid-template-columns:repeat(3,1fr)"><div class="metric"><div class="metric-label">Asuntos abiertos</div><div class="metric-number">${pending.length}</div></div><div class="metric"><div class="metric-label">Riesgos identificados</div><div class="metric-number">${t.filter(x=>x.type==='Riesgo').length}</div></div><div class="metric"><div class="metric-label">Decisiones pendientes</div><div class="metric-number">${t.filter(x=>x.type==='Decisión'&&x.status!=='Resuelto').length}</div></div></div><div class="split"><div class="stack">${sections.map(section=>`<section class="surface surface-pad"><div class="section-head"><h2>${section==='Riesgo'?'Riesgos':section==='Decisión'?'Decisiones':section==='Pendiente'?'Pendientes':'Próximos pasos'}</h2><span class="tiny muted">${t.filter(x=>x.type===section).length} ELEMENTOS</span></div>${t.filter(x=>x.type===section).map(x=>`<div class="note-item"><div class="note-icon">${I(section==='Riesgo'?'alert-triangle':section==='Decisión'?'check-check':'clock')}</div><div class="grow"><strong>${e(x.title)}</strong><p>${e(x.detail)}</p><div class="actions-row" style="margin-top:9px">${statusPill(x.status)}<button class="link-btn" data-edit="tasks" data-id="${x.id}">Editar</button></div></div></div>`).join('')||'<div class="empty">Aún no hay registros.</div>'}</section>`).join('')}</div><aside class="surface surface-pad"><div class="eyebrow">CONTROL DE CAMBIOS</div><h2>Actividad reciente</h2>${all('events').slice().reverse().slice(0,12).map(x=>`<div class="note-item"><div class="note-icon">${I('check')}</div><div><strong>${e(x.text)}</strong><p>${e(x.user)} · ${date(x.date)}</p></div></div>`).join('')||'<p class="muted">Las acciones del equipo se registrarán aquí.</p>'}</aside></div>`}
function launchPage(){let ck=all('checklist');const done=ck.filter(x=>x.done).length;return heading('PREPARACIÓN / SALIDA','Publicación responsable','Verifica las conexiones y flujos esenciales antes de usar datos reales.')+`<div class="split"><section class="surface surface-pad"><div class="section-head"><h2>Checklist de publicación</h2><span class="pill ${done===ck.length?'green':'orange'}">${done} / ${ck.length} verificados</span></div><div class="progress-track" role="progressbar" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${ck.length}"><div class="progress-fill" style="width:${done/Math.max(ck.length,1)*100}%"></div></div><p class="muted" style="margin:13px 0 17px">Marca una tarea únicamente cuando la hayas probado y confirmado.</p>${ck.map(x=>`<label class="checkbox-row ${x.done?'task-done':''}"><input type="checkbox" data-check="${x.id}" ${x.done?'checked':''} ${!canEdit('tasks')?'disabled':''}/><span><strong>${e(x.title)}</strong></span></label>`).join('')}<div class="notice"><strong>Importante:</strong> completar este checklist no activa por sí solo las integraciones externas.</div></section><aside class="stack"><section class="setting-panel"><div class="eyebrow">01 / DATOS</div><h3>Persistencia compartida</h3><p>Hoy los registros se almacenan únicamente en IndexedDB de este navegador. Para acceder desde varios dispositivos será necesario migrarlos a Supabase con autenticación y RLS.</p><button class="btn btn-small" data-nav="settings">Preparar Supabase ${I('chevron-right')}</button></section><section class="setting-panel"><div class="eyebrow">02 / COMUNICACIONES</div><h3>Correo transaccional</h3><p>Los correos de prueba se registran localmente, sin envío por SMTP/API. El flujo final debe usar una función segura en servidor.</p><button class="btn btn-small" data-nav="settings">Configurar correo ${I('chevron-right')}</button></section><section class="setting-panel"><div class="eyebrow">03 / WEB</div><h3>Vercel / Cloudflare Pages</h3><p>El proyecto está preparado como sitio estático desplegable. La vista permite registrar dominio, proyecto y URL.</p><button class="btn btn-small" data-nav="settings">Ver despliegue ${I('chevron-right')}</button></section></aside></div>`}
function settingsPage(){const s=all('settings')[0]||{};return heading('PREFERENCIAS / ESTUDIO','Configuración','Identidad, comunicación, datos y despliegue de Daya Clothing.')+`<div class="split"><section><form id="settings-form"><div class="setting-panel"><div class="eyebrow">01 / IDENTIDAD</div><h3>Datos de la tienda</h3><p>Información que se usará en el panel y en las comunicaciones.</p><div class="grid2"><div class="field"><label for="shop-brand">Nombre comercial</label><input id="shop-brand" name="brand" required value="${e(s.brand)}"/></div><div class="field"><label for="shop-email">Correo de contacto</label><input id="shop-email" name="email" type="email" required value="${e(s.email)}"/></div><div class="field"><label for="shop-sender">Nombre del remitente</label><input id="shop-sender" name="sender" required value="${e(s.sender)}"/></div><div class="field"><label for="shop-test">Destino de pruebas</label><input id="shop-test" name="testEmail" type="email" required value="${e(s.testEmail)}"/></div></div></div><div class="setting-panel"><div class="eyebrow">02 / DATOS</div><h3>Supabase · preparación</h3><p>Registra identificadores no secretos para el futuro backend compartido. No introduzcas claves privadas aquí.</p><div class="field"><label for="supabase-url">URL pública del proyecto</label><input id="supabase-url" name="supabaseUrl" type="url" placeholder="https://tu-proyecto.supabase.co" value="${e(s.supabaseUrl)}"/><small class="field-hint">Esto solo guarda la referencia. No conecta automáticamente ni habilita Auth/RLS.</small></div></div><div class="setting-panel"><div class="eyebrow">03 / DESPLIEGUE</div><h3>Vercel / Cloudflare Pages & dominio</h3><p>Registra el destino de publicación. La configuración de DNS y servicios se hace desde las respectivas plataformas.</p><div class="grid2"><div class="field"><label for="cf-project">Proyecto Cloudflare Pages</label><input id="cf-project" name="cloudflareProject" placeholder="daya-clothing" value="${e(s.cloudflareProject)}"/></div><div class="field"><label for="domain">Dominio propio</label><input id="domain" name="domain" placeholder="dayaclothing.com.mx" value="${e(s.domain)}"/></div><div class="field full"><label for="site-url">URL de vista previa</label><input id="site-url" name="siteUrl" type="url" placeholder="https://daya-clothing.vercel.app" value="${e(s.siteUrl)}"/></div></div></div><div class="actions-row" style="margin:18px 0 28px"><button class="btn btn-primary" type="submit">${I('check')} Guardar configuración</button></div></form></section><aside class="stack"><section class="setting-panel"><div class="eyebrow">BANDEJA / PRUEBAS</div><h3>Correos de prueba</h3><p>Genera un correo de ejemplo dirigido al correo configurado y consérvalo en la bandeja local.</p><button class="btn btn-primary" data-action="test-mail">${I('mail')} Generar correo de prueba</button><div class="bar"></div><h3 style="font:500 17px var(--serif)">Bandeja de salida simulada</h3>${all('outbox').slice().reverse().slice(0,8).map(x=>`<div class="note-item"><div class="note-icon">${I('mail')}</div><div><strong>${e(x.subject)}</strong><p>Para: ${e(x.to)}<br/>${date(x.date)} · Solo registro local</p></div></div>`).join('')||'<p class="muted">Todavía no se han generado mensajes.</p>'}<div class="notice">No se envían correos reales desde esta versión.</div></section><section class="setting-panel"><div class="eyebrow">CÓPIAS / CONTROL</div><h3>Datos locales</h3><p>Exporta la información como JSON para respaldo, importa un respaldo previo o restaura la demostración.</p><div class="stack"><button class="btn" data-action="export">${I('download')} Exportar respaldo JSON</button><label class="btn import-label" for="import-file">${I('upload')} Importar respaldo JSON<input type="file" id="import-file" class="file-control" accept="application/json"/></label><button class="btn btn-danger" data-action="reset-data">${I('trash')} Restablecer datos de ejemplo</button></div></section></aside></div>`}
function emptyView(title,desc,resource){return `<div class="surface"><div class="empty">${I('package')}<h3>${e(title)}</h3><p>${e(desc)}</p>${addBtn(resource,'Crear registro')}</div></div>`}

/* Requests placed through the public demo storefront. Review-only: confirmation does NOT mutate stock or create an actual order. */
function getWebRequests(){try{const x=JSON.parse(localStorage.getItem('daya-web-inquiries-v1')||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function requestsPage(){const requests=getWebRequests();const rows=requests.map(r=>`<tr><td><strong>${e(r.id)}</strong><br><small>${date(r.created)}</small></td><td><strong>${e(r.name)}</strong><br><small>${e(r.email)}</small><br><small>${e(r.phone)}</small></td><td>${(r.items||[]).map(i=>`${e(i.qty)} × ${e(i.name)} <small>${e(i.size||'')} ${e(i.color||'')}</small>`).join('<br>')}</td><td><strong>${fmt(r.total)}</strong></td><td>${statusPill(r.status)}</td><td>${canEdit('orders')&&r.status==='Por confirmar'?`<button class="btn btn-small" data-action="request-status" data-id="${e(r.id)}" data-status="Revisada">Marcar revisada</button>`:''}</td></tr>`).join('');return heading('TIENDA / PEDIDOS ENTRANTES','Solicitudes desde la web','Pedidos simulados recibidos en este navegador. Revísalos y crea el pedido real desde la sección Pedidos para ajustar el inventario.')+`<div class="surface surface-pad"><p class="muted">Estas solicitudes no generan cobros, envíos de correo ni descuentos de inventario automáticamente. Solo son visibles en el mismo navegador y origen de la tienda.</p></div><div style="height:18px"></div>`+table(['Solicitud','Cliente','Artículos','Importe','Estado','Acción'],rows,'Todavía no hay solicitudes desde la tienda.');}
async function updateRequestStatus(id,status){if(!canEdit('orders'))return flash('Permisos insuficientes',true);const requests=getWebRequests();const item=requests.find(x=>x.id===id);if(!item)return flash('No se encontró la solicitud',true);item.status=status;localStorage.setItem('daya-web-inquiries-v1',JSON.stringify(requests));await log('Se actualizó solicitud web '+id+' a '+status);render();flash('Solicitud marcada como '+status)}

function enhanceStudioUI(){
  document.querySelectorAll('.data-table').forEach(table=>{
    table.setAttribute('role','table');
    table.querySelectorAll('thead,tbody').forEach(group=>group.setAttribute('role','rowgroup'));
    table.querySelectorAll('tr').forEach(row=>row.setAttribute('role','row'));
    table.querySelectorAll('th').forEach(cell=>cell.setAttribute('role','columnheader'));
    table.querySelectorAll('td').forEach(cell=>cell.setAttribute('role','cell'));
    const headings=[...table.querySelectorAll('thead th')];
    headings.forEach(th=>th.scope='col');
    table.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((cell,index)=>{
      if(cell.colSpan===1){
        cell.dataset.label=headings[index]?.textContent||'';
        const value=document.createElement('div');
        value.className='cell-value';
        value.append(...cell.childNodes);
        cell.append(value);
      }
    }));
  });
}
function render(resetScroll=false){if(!me()){loginUI();return;}if(!canView(state.section))state.section='dashboard';const views={dashboard,products:productsPage,orders:ordersPage,requests:requestsPage,customers:customersPage,users:usersPage,tasks:tasksPage,launch:launchPage,settings:settingsPage};shell((views[state.section]||dashboard)());enhanceStudioUI();if(resetScroll)window.scrollTo({top:0,behavior:'instant'})}
function nav(to){if(!canView(to)){flash('No tienes permiso para acceder a esta sección.',true);return}state.section=to;state.query='';state.filter='Todos';location.hash=to;render(true);document.getElementById('studio-main')?.focus({preventScroll:true})}
function fval(f,k){return (f.get(k)||'').toString().trim()}
function selectField(name,label,options,value='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}>${options.map(o=>`<option value="${e(o)}" ${o===value?'selected':''}>${e(o)}</option>`).join('')}</select></div>`}
function inputField(name,label,value='',type='text',required=true,attributes=''){return `<div class="field"><label for="f-${name}">${e(label)}</label><input id="f-${name}" type="${type}" name="${name}" value="${e(value)}" ${required?'required':''} ${attributes}/></div>`}
function textareaField(name,label,value=''){return `<div class="field full"><label for="f-${name}">${e(label)}</label><textarea name="${name}" id="f-${name}">${e(value)}</textarea></div>`}
let modalOpener=null;
function openModal(title,formHTML,resource,id=''){
  modalOpener=document.activeElement;
  const readonly=!canEdit(resource);
  document.getElementById('dialog-layer').innerHTML=`<div class="modal-backdrop" data-dismiss="modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><h2 id="modal-title">${e(title)}</h2><button type="button" class="icon-btn" data-dismiss="modal" aria-label="Cerrar">${I('x')}</button></header><form id="record-form" data-resource="${resource}" data-id="${e(id)}"><div class="modal-body"><div class="grid2">${formHTML}</div></div><footer class="modal-footer"><button type="button" class="btn" data-dismiss="modal">${readonly?'Cerrar':'Cancelar'}</button>${!readonly?`<button class="btn btn-primary" type="submit">${I('check')} Guardar cambios</button>`:''}</footer></form></section></div>`;
  const root=document.querySelector('#record-form');
  if(readonly)root.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=true);
  document.body.style.overflow='hidden';
  document.getElementById('app').inert=true;
  document.querySelector('.studio-banner').inert=true;
  document.querySelector('.skip-link').inert=true;
  document.querySelector('.modal .icon-btn')?.focus();
}
function closeModal(){
  if(!document.querySelector('.modal'))return;
  const opener=modalOpener;
  const selector=opener?.dataset.edit?`[data-edit="${CSS.escape(opener.dataset.edit)}"][data-id="${CSS.escape(opener.dataset.id||'')}"]`:opener?.dataset.add?`[data-add="${CSS.escape(opener.dataset.add)}"]`:null;
  document.getElementById('dialog-layer').innerHTML='';
  document.body.style.overflow='';
  document.getElementById('app').inert=false;
  document.querySelector('.studio-banner').inert=false;
  document.querySelector('.skip-link').inert=false;
  requestAnimationFrame(()=>{
    const target=opener?.isConnected?opener:selector?document.querySelector(selector):null;
    (target||document.getElementById('studio-main'))?.focus({preventScroll:true});
  });
  modalOpener=null;
}
function productModal(obj){const p=obj||{};openModal(obj?'Editar producto':'Nuevo producto',`${inputField('name','Nombre del producto',p.name||'')}${inputField('sku','SKU / código',p.sku||'')}${selectField('category','Categoría',CATEGORIES,p.category||'Blusas')}${selectField('status','Estado',PRODUCT_STATUSES,p.status||'Activo')}${inputField('price','Precio de venta (MXN)',p.price||'','number',true,'min="0" step=".01"')}${inputField('cost','Costo estimado (MXN)',p.cost||'','number',false,'min="0" step=".01"')}${inputField('stock','Unidades disponibles',p.stock??0,'number',true,'min="0" step="1"')}${inputField('minStock','Alerta de stock',p.minStock??6,'number',true,'min="0" step="1"')}${inputField('sizes','Tallas (separadas por comas)',p.sizes||'', 'text',false)}${inputField('colors','Colores (separados por comas)',p.colors||'','text',false)}<div class="field full"><label for="image-preset">Fotografía del producto</label><div class="upload-preview"><img id="image-preview" src="${e(p.image||IMG[0])}" alt="Vista previa"/><div><select id="image-preset" name="imagePreset" style="width:100%;margin-bottom:7px"><option value="">Imagen actual</option>${IMG.map((src,i)=>`<option value="${src}">${['Blusa de lino','Cárdigan','Vestido','Jeans','Bolso borgoña','Sandalias','Aretes','Blusa rosa','Bolso tejido'][i]}</option>`).join('')}</select><input type="file" id="image-file" aria-label="Subir fotografía del producto" accept="image/png,image/jpeg,image/webp"/><small class="field-hint">Se optimiza a WebP y se guarda localmente.</small></div></div></div>`,'products',p.id||'');const form=document.getElementById('record-form');form.dataset.image=p.image||IMG[0];}
function customerModal(obj){const c=obj||{};openModal(obj?'Editar cliente':'Nuevo cliente',`${inputField('name','Nombre completo',c.name||'')}${inputField('phone','Teléfono',c.phone||'','tel',true,'minlength="10"')}${inputField('email','Correo electrónico',c.email||'','email')}${inputField('city','Ciudad',c.city||'')}${textareaField('note','Notas de contacto',c.note||'')}`,'customers',c.id||'')}
function orderLine(item={}){return `<div class="field"><label>Producto<select name="productId" class="order-product" required>${all('products').filter(p=>p.status==='Activo'||p.id===item.productId).map(p=>`<option value="${e(p.id)}" ${p.id===item.productId?'selected':''}>${e(p.name)} — ${fmt(p.price)} · ${p.stock} disp.</option>`).join('')}</select></label></div><div class="field"><label>Cantidad<input type="number" name="qty" class="order-qty" value="${item.qty||1}" min="1" step="1" required/></label></div>`}
function orderModal(obj){const o=obj||{};const items=(o.items&&o.items.length?o.items:[{productId:all('products').find(x=>x.status==='Activo')?.id,qty:1}]);openModal(obj?`Gestionar ${o.id}`:'Nuevo pedido',`${selectField('customerId','Cliente',all('customers').map(c=>c.id+'|'+c.name),o.customerId?o.customerId+'|'+(all('customers').find(c=>c.id===o.customerId)?.name||''):'')}${selectField('status','Estado',ORDER_STATUSES,o.status||'Nuevo')}${selectField('channel','Canal',['Instagram','WhatsApp','Web','Tienda física','Otro'],o.channel||'Instagram')}<div class="field"><label for="order-date">Fecha</label><input id="order-date" type="date" name="orderDate" value="${(o.date||new Date().toISOString()).slice(0,10)}" required /></div><div class="field full"><div class="field-label">Artículos del pedido</div><div id="order-lines" class="grid2" style="gap:10px">${items.map(orderLine).join('')}</div>${!obj?`<button type="button" class="btn btn-small" data-action="add-line" style="margin-top:11px">${I('plus')} Agregar otro artículo</button>`:''}<small class="field-hint">Al crear el pedido se descuenta el inventario. Si se cancela, se devuelve.</small></div>${textareaField('note','Notas del pedido',o.note||'')}`,'orders',o.id||'');if(obj){document.querySelector('#record-form [name="customerId"]').disabled=true;document.querySelectorAll('#order-lines select,#order-lines input').forEach(x=>x.disabled=true)}const sel=document.querySelector('#record-form [name="customerId"]');if(sel){for(const x of sel.options)x.text=x.text.split('|')[1]||x.text;}}
function userModal(obj){const u=obj||{};openModal(obj?'Editar acceso':'Nuevo integrante',`${inputField('name','Nombre completo',u.name||'')}${inputField('email','Correo para ingresar',u.email||'','email')}${selectField('role','Perfil',['Administrador','Operador','Consulta'],u.role||'Operador')}${selectField('status','Estado',['Activo','Inactivo'],u.status||'Activo')}${inputField('password','Contraseña demostrativa', '', 'password',!obj,'minlength="8" autocomplete="new-password"')}<div class="field full"><div class="notice">Solo para probar roles en este navegador. En producción las contraseñas deben gestionarse mediante Supabase Auth, nunca desde esta pantalla.</div></div>`,'users',u.id||'')}
function taskModal(obj){const t=obj||{};openModal(obj?'Editar seguimiento':'Nuevo seguimiento',`${selectField('type','Tipo',['Decisión','Pendiente','Riesgo','Próximo paso'],t.type||'Pendiente')}${selectField('status','Situación',['Pendiente','En curso','Abierto','Resuelto'],t.status||'Pendiente')}${inputField('title','Título',t.title||'')}<div class="field full">${textareaField('detail','Detalles',t.detail||'')}</div>`,'tasks',t.id||'')}
function openRecord(s,id){if(!canView(s))return flash('Acceso no permitido',true);const obj=id?all(s).find(x=>x.id===id):undefined;if(id&&!obj)return flash('No se encontró el registro',true);if(!id&&!canEdit(s))return flash('No tienes permiso para crear registros',true);({products:productModal,orders:orderModal,customers:customerModal,users:userModal,tasks:taskModal}[s]||(()=>{}))(obj)}
async function encodeImage(file){if(file.size>7*1024*1024)throw Error('La imagen debe pesar menos de 7 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Formato de imagen no compatible.');const img=await createImageBitmap(file);const cv=document.createElement('canvas');const scale=Math.min(1,850/Math.max(img.width,img.height));cv.width=Math.max(1,Math.round(img.width*scale));cv.height=Math.max(1,Math.round(img.height*scale));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);img.close();return cv.toDataURL('image/webp',.82)}
async function saveResource(ev){ev.preventDefault();const form=ev.currentTarget;const s=form.dataset.resource;const id=form.dataset.id; if(!canEdit(s))return flash('Permisos insuficientes',true);const f=new FormData(form);const existing=id?all(s).find(x=>x.id===id):null;if(id&&!existing)return flash('El registro ya no existe',true);let obj={...(existing||{}),id:id||uid(s.slice(0,2).toUpperCase())};try{
if(s==='products'){const name=fval(f,'name'),sku=fval(f,'sku');const price=Number(fval(f,'price')),stock=Number(fval(f,'stock')),cost=Number(fval(f,'cost')||0),minStock=Number(fval(f,'minStock'));if(!name||!sku||price<0||stock<0||!Number.isInteger(stock)||!Number.isInteger(minStock)||minStock<0||cost<0)throw Error('Completa los campos y verifica precios y existencias.');if(all('products').some(p=>p.sku.toLowerCase()===sku.toLowerCase()&&p.id!==id))throw Error('Ese SKU ya está registrado.');Object.assign(obj,{name,sku,category:fval(f,'category'),status:fval(f,'status'),price,stock,cost,minStock,sizes:fval(f,'sizes'),colors:fval(f,'colors'),image:form.dataset.image||IMG[0],created:obj.created||new Date().toISOString()});}
if(s==='customers'){const name=fval(f,'name'),phone=fval(f,'phone'),email=fval(f,'email');if(name.length<2||!/^\d[\d+\s-]{8,}$/.test(phone))throw Error('Revisa nombre y teléfono (mínimo 9 dígitos).');if(all('customers').some(c=>c.email.toLowerCase()===email.toLowerCase()&&c.id!==id))throw Error('Ya existe un cliente con ese correo.');Object.assign(obj,{name,phone,email,city:fval(f,'city'),note:fval(f,'note'),created:obj.created||new Date().toISOString()});}
if(s==='orders'){const customerId=id?existing.customerId:fval(f,'customerId').split('|')[0];if(!all('customers').some(c=>c.id===customerId))throw Error('Selecciona un cliente registrado.');if(id){let newStatus=fval(f,'status');if(existing.status!==newStatus){const restore=existing.status!=='Cancelado'&&newStatus==='Cancelado',reserve=existing.status==='Cancelado'&&newStatus!=='Cancelado';const updated=[];for(const item of existing.items){const p=all('products').find(x=>x.id===item.productId);if(!p)throw Error('Producto no encontrado para ajuste de stock.');if(reserve&&p.stock<item.qty)throw Error(`Stock insuficiente para ${p.name}.`);if(restore||reserve)updated.push({...p,stock:p.stock+(restore?item.qty:-item.qty)})}await storage.batch(updated.map(data=>({s:'products',data})));}Object.assign(obj,{status:newStatus,channel:fval(f,'channel'),note:fval(f,'note'),date:fval(f,'orderDate')+'T12:00:00.000Z'});}else{const products=[...form.querySelectorAll('.order-product')],qtys=[...form.querySelectorAll('.order-qty')];const quantities={};products.forEach((select,i)=>{const q=Number(qtys[i].value);if(!Number.isInteger(q)||q<=0)throw Error('Las cantidades deben ser enteros positivos.');quantities[select.value]=(quantities[select.value]||0)+q});const items=[];const updates=[];let total=0;for(const [pId,qty] of Object.entries(quantities)){const p=all('products').find(x=>x.id===pId);if(!p)throw Error('Uno de los productos no existe.');if(fval(f,'status')!=='Cancelado'&&p.stock<qty)throw Error(`No hay suficiente stock de ${p.name} (${p.stock} disponibles).`);items.push({productId:p.id,qty,price:p.price});total+=p.price*qty;if(fval(f,'status')!=='Cancelado')updates.push({...p,stock:p.stock-qty});}obj={id:'DY-'+String(Date.now()).slice(-7),customerId,items,total,status:fval(f,'status'),channel:fval(f,'channel'),date:fval(f,'orderDate')+'T12:00:00.000Z',note:fval(f,'note')};await storage.batch([...updates.map(data=>({s:'products',data})),{s:'orders',data:obj}]);await log('Se registró el pedido '+obj.id);await load();closeModal();render();flash('Pedido guardado e inventario actualizado');return;}}
if(s==='users'){const email=fval(f,'email'),pass=fval(f,'password');if(!fval(f,'name'))throw Error('Introduce un nombre.');if(all('users').some(x=>x.email===email&&x.id!==id))throw Error('Ya existe un usuario con ese correo.');if(!id&&pass.length<8)throw Error('La contraseña debe tener al menos 8 caracteres.');if(id&&obj.id===me().id&&fval(f,'status')==='Inactivo')throw Error('No puedes desactivar tu propia cuenta.');if(id&&obj.id===me().id&&fval(f,'role')!=='Administrador')throw Error('No puedes quitarte tu propio permiso de administración.');Object.assign(obj,{name:fval(f,'name'),email,role:fval(f,'role'),status:fval(f,'status'),passwordHash:pass?await hashPass(pass):obj.passwordHash});}
if(s==='tasks'){if(!fval(f,'title'))throw Error('Escribe el título.');Object.assign(obj,{type:fval(f,'type'),status:fval(f,'status'),title:fval(f,'title'),detail:fval(f,'detail'),date:obj.date||new Date().toISOString()});}
await storage.put(s,obj);await log(`${id?'Se actualizó':'Se creó'} ${s==='products'?'producto':s==='customers'?'cliente':s==='users'?'usuario':s==='tasks'?'seguimiento':'pedido'}: ${obj.name||obj.title||obj.id}`);await load();closeModal();render();flash('Cambios guardados correctamente');}catch(err){flash(err.message||'No fue posible guardar el registro.',true)}}
async function saveSettings(ev){ev.preventDefault();if(!admin())return;const f=new FormData(ev.currentTarget);const obj={id:'shop'};for(const key of ['brand','email','testEmail','sender','supabaseUrl','cloudflareProject','domain','siteUrl'])obj[key]=fval(f,key);if(obj.domain&&(!/^(?:[a-z0-9-]+\.)+[a-z]{2,}$/i.test(obj.domain)))return flash('Introduce un dominio sin https:// (ejemplo: dayaclothing.com.mx)',true);if(obj.supabaseUrl&&!/^https:\/\/[a-z0-9.-]+\.supabase\.co\/?$/i.test(obj.supabaseUrl))return flash('La URL de Supabase debe terminar en .supabase.co',true);await storage.put('settings',obj);await log('Se actualizó la configuración local');await load();render();flash('Configuración guardada en este dispositivo')}
async function doExport(){if(!admin())return;const data={format:'daya-studio-backup',version:1,created:new Date().toISOString(),data:Object.fromEntries(STORES.filter(s=>s!=='meta').map(s=>[s,all(s)]))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='daya-studio-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);flash('Respaldo JSON descargado')}
async function doImport(file){if(!admin())return;if(file.size>15*1024*1024)return flash('El respaldo excede 15 MB.',true);try{const json=JSON.parse(await file.text());if(json.format!=='daya-studio-backup'||json.version!==1||!json.data||!Array.isArray(json.data.products)||!Array.isArray(json.data.users))throw Error('Formato de respaldo no compatible.');if(!confirm('¿Reemplazar TODOS los datos locales por este respaldo?'))return;for(const s of STORES.filter(s=>s!=='meta'))await storage.clear(s);for(const s of STORES.filter(s=>s!=='meta'))for(const obj of json.data[s]||[])if(obj.id)await storage.put(s,obj);await load();if(!all('users').some(x=>x.id===me().id&&x.status==='Activo')){logout();flash('Respaldo importado. Vuelve a ingresar.');return;}render();flash('Respaldo importado correctamente')}catch(err){flash(err.message||'No se pudo importar el archivo',true)}}
async function testMail(){if(!admin())return;const to=all('settings')[0]?.testEmail||DEFAULT_EMAIL;const mail={id:uid('MAIL'),to,subject:'[PRUEBA] Daya Clothing · Notificación de pedido',body:'Este es un correo de demostración generado por Daya Clothing Studio. No se ha enviado a ningún proveedor de email.',date:new Date().toISOString(),status:'Simulado / no enviado'};await storage.put('outbox',mail);await log('Se generó un correo local de prueba para '+to);await load();render();flash('Correo simulado guardado en bandeja local (no enviado)')}
function handleClick(ev){const el=ev.target.closest('[data-nav],[data-add],[data-edit],[data-action],[data-dismiss]');if(!el)return;if(el.dataset.dismiss){if(el.dataset.dismiss==='modal'&&(ev.target===el||el.tagName==='BUTTON'))closeModal();return}if(el.dataset.nav){nav(el.dataset.nav);return}if(el.dataset.add){openRecord(el.dataset.add);return}if(el.dataset.edit){openRecord(el.dataset.edit,el.dataset.id);return}if(el.dataset.action){const a=el.dataset.action;if(a==='logout')logout();if(a==='request-status')updateRequestStatus(el.dataset.id,el.dataset.status);if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;localStorage.setItem('daya-theme',state.theme);render()}if(a==='toggle-gallery'){state.gallery=!state.gallery;render()}if(a==='reset-filter'){state.query='';state.filter='Todos';render()}if(a==='export')doExport();if(a==='test-mail')testMail();if(a==='reset-data'&&admin()&&confirm('Esto eliminará todos los datos locales, incluidas las modificaciones y los nuevos usuarios. ¿Continuar?')){seed(true).then(async()=>{await load();logout();flash('Datos de demostración restaurados')}).catch(x=>flash(x.message,true))}if(a==='add-line'){const wrap=document.getElementById('order-lines');if(wrap)wrap.insertAdjacentHTML('beforeend',orderLine())}}}
document.addEventListener('click',handleClick);
document.addEventListener('submit',async ev=>{if(ev.target.id==='login-form'){ev.preventDefault();const f=new FormData(ev.target);try{await login(fval(f,'email'),fval(f,'password'))}catch(err){flash(err.message,true)}}else if(ev.target.id==='record-form')saveResource(ev);else if(ev.target.id==='settings-form')saveSettings(ev)});
document.addEventListener('change',async ev=>{if(ev.target.id==='page-filter'){state.filter=ev.target.value;render()}if(ev.target.dataset.check){if(!canEdit('tasks'))return;const o=all('checklist').find(x=>x.id===ev.target.dataset.check);if(o){await storage.put('checklist',{...o,done:ev.target.checked});await load();render();flash('Checklist actualizado')}}if(ev.target.id==='image-preset'){const form=document.getElementById('record-form');if(ev.target.value){form.dataset.image=ev.target.value;document.getElementById('image-preview').src=ev.target.value}}if(ev.target.id==='image-file'&&ev.target.files?.length){try{const img=await encodeImage(ev.target.files[0]);const form=document.getElementById('record-form');form.dataset.image=img;document.getElementById('image-preview').src=img;flash('Imagen optimizada y lista para guardar')}catch(err){flash(err.message,true)}}if(ev.target.id==='import-file'&&ev.target.files?.[0])doImport(ev.target.files[0])});
document.addEventListener('input',ev=>{if(ev.target.id==='page-search'){const selection=ev.target.selectionStart;state.query=ev.target.value;const focus=document.activeElement===ev.target;render();if(focus){const t=document.getElementById('page-search');t?.focus();t?.setSelectionRange(selection,selection)}}});
document.addEventListener('keydown',ev=>{
  const modal=document.querySelector('.modal');
  if(!modal)return;
  if(ev.key==='Escape'){ev.preventDefault();closeModal();return;}
  if(ev.key!=='Tab')return;
  const focusable=[...modal.querySelectorAll('button,input,select,textarea,a[href],[tabindex]')].filter(el=>!el.disabled&&el.tabIndex>=0&&el.getClientRects().length);
  const first=focusable[0],last=focusable.at(-1);
  if(!first){ev.preventDefault();modal.focus();return;}
  if(ev.shiftKey&&(document.activeElement===first||document.activeElement===modal)){ev.preventDefault();last.focus();}
  else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}
});
window.addEventListener('hashchange',()=>{if(!state.user)return;const target=location.hash.slice(1);if(navs.some(x=>x[0]===target)&&target!==state.section)nav(target)});
(async()=>{try{await storage.init();await seed();await load();const sess=JSON.parse(sessionStorage.getItem('daya-session')||'null');if(sess&&sess.expiresAt>Date.now()){const u=all('users').find(x=>x.id===sess.userId&&x.status==='Activo');if(u)state.user={id:u.id,name:u.name,email:u.email,role:u.role}}if(state.user){let target=location.hash.slice(1);state.section=navs.some(x=>x[0]===target)&&canView(target)?target:'dashboard';}render();if('serviceWorker' in navigator && ['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>{});}catch(err){console.error(err);document.getElementById('app').innerHTML=`<main style="padding:12vw;font-family:system-ui"><h1>No pudimos abrir la base local</h1><p>Este navegador debe permitir IndexedDB. Abre el proyecto desde un servidor HTTP o HTTPS, no en modo privado restringido.</p><pre>${e(err.message)}</pre></main>`}})();
